# Kaggle script kernel (CPU): forward-mode AD leads (ldexp crash, addr _make_dual assert) on Linux, torch 2.14.0 then nightly.
import base64, subprocess, sys
open("diag_jvp_ldexp_crash.py", "wb").write(base64.b64decode(""))
open("diag_jvp_addr.py", "wb").write(base64.b64decode(""))
for spec in (["torch==2.14.0", "--index-url", "https://download.pytorch.org/whl/cpu"], ["--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cpu"]):
    subprocess.run(["pip", "-q", "install", *spec])
    subprocess.run([sys.executable, "diag_jvp_ldexp_crash.py"])
    subprocess.run([sys.executable, "diag_jvp_addr.py"])
print("JOB DONE", flush=True)
